     "time": "08-17 19:10",
     "ts": 1786965041,
     "summary": "智东西 作者 | 王涵 编辑 | 漠影 还有两天，8月19日，2026世界机器人大会将在北京亦庄正式开幕。 本届大会的主题定为“产需共融”，背后传递出一个十分现实的行业信号：机器人行业的比拼，已经不再单纯看纸面技术参数有多亮眼，而是要看产品能不能真正拿到市场订单。 所谓“产需共融”，其实就是供给端造得出，需求端愿意买。顺着这个思路看，小型商用清洁机器人，大概率会成为今年机器人行业被高频探讨的典型案例。 为什么这么说？因为这类场景的清洁需求一直客观存在，但始终没有得到很好的解决",
