     "summary": "21世纪经济报道记者 董静怡 乌兰察布报道从乌兰察布高铁站出来，迎面是明晃晃的太阳和干燥的风。八月的傍晚，气温不过二十度出头。我打了一辆出租车，和司机说：“我想看看这里的数据中心。”司机师傅老陈热情地接待了我。老陈看起来已年过六旬，但他对于这个有些“专业”的词汇并不陌生，不看导航也轻车熟路。我有些意外。车拐上了一条宽阔的马路，向乌兰察布的东郊驶去。老陈和我说，这条路是前几年修的...",
