     "summary": "8月18日(星期二)，今日报刊头条主要内容精华如下： 中国证券报 两部门发文提出2030年国内油气供应量目标 锚定保障能源安全和绿色低碳发展任务 8月17日，国家发展改革委网站消息，国家发展改革委、国家能源局日前印发《石油天然气发展“十五五”规划》（简称《规划》）。《规划》锚定保障能源安全和绿色低碳发展两大任务。明确到2030年，国内油气供应量达4.4亿吨油当量，新增油气长输管道2万公里，全国油气长输管网规模达22万公里，天然气储备规模持续增长，占全国消费比重超过13%，液化",
